A=[]
def add(path,cat,desc,alt,source,use,credit=None,notes=None):
    full=ROOT+path
    assert os.path.exists(full),path
    w,h=Image.open(full).size
    d=dict(path=path,category=cat,description=desc,alt=alt,source=source,width=w,height=h,suggested_use=use,credit=credit)
    if notes: d['notes']=notes
    A.append(d)
