def printed(pdfp):
    if pdfp<=9: return ['i','ii','iii','iv','v','vi','vii','viii','ix'][pdfp-1]
    if pdfp>=142 and pdfp<=182: return f'A2-{pdfp-141}'
    return str(pdfp-9)
